import pandas as pd
from datetime import timedelta

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark_df = inputs["watermark"]

    # Extract high_ts from watermark
    high_ts = watermark_df["high_ts"].iloc[0]

    # Filter events strictly greater than watermark
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    if len(new_events) == 0:
        # No new events, return current snapshot
        return {"new_snapshot": target_snapshot}

    # Sort events by user_id, then by event_ts, then by event_seq for deterministic processing
    new_events = new_events.sort_values(
        by=["user_id", "event_ts", "event_seq"],
        ascending=[True, True, True]
    ).reset_index(drop=True)

    # Create a dictionary from current snapshot for fast lookup
    snapshot_dict = {}
    for _, row in target_snapshot.iterrows():
        user_id = row["user_id"]
        snapshot_dict[user_id] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process events sequentially per user
    for _, event in new_events.iterrows():
        user_id = event["user_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        email = event["email"]

        if user_id not in snapshot_dict:
            # New user
            if op == "U":
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }
            elif op == "D":
                # Delete on new user
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": event_ts
                }
        else:
            current = snapshot_dict[user_id]

            if op == "D":
                # Soft delete
                current["email"] = email
                current["status"] = "DELETED"
                current["status_ts"] = event_ts
            elif op == "U":
                # Update
                if current["status"] == "ACTIVE":
                    # Active user: always accept update
                    current["email"] = email
                    current["status"] = "ACTIVE"
                    current["status_ts"] = event_ts
                elif current["status"] == "DELETED":
                    # Check resurrection window: strictly more than 7 days
                    days_since_delete = event_ts - current["status_ts"]
                    seven_days = timedelta(days=7)

                    if days_since_delete > seven_days:
                        # Resurrection allowed
                        current["email"] = email
                        current["status"] = "ACTIVE"
                        current["status_ts"] = event_ts
                    # else: discard update (deletion is sticky)

    # Convert dictionary back to DataFrame
    result_rows = []
    for user_id, data in snapshot_dict.items():
        result_rows.append({
            "user_id": user_id,
            "email": data["email"],
            "status": data["status"],
            "status_ts": data["status_ts"]
        })

    new_snapshot = pd.DataFrame(result_rows)

    # Ensure correct dtypes
    if len(new_snapshot) > 0:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"], utc=False).astype("datetime64[us]")
    else:
        # Empty result with correct schema
        new_snapshot = pd.DataFrame({
            "user_id": pd.Series([], dtype="int64"),
            "email": pd.Series([], dtype="object"),
            "status": pd.Series([], dtype="object"),
            "status_ts": pd.Series([], dtype="datetime64[us]")
        })

    return {"new_snapshot": new_snapshot}
